import pytest
from attr.validators import instance_of
from attr import attrs, attrib

@attrs
class MyClass:
    x = attrib()

def test_instance_of_with_subclass_instance():
    class SubClass(MyClass):
        pass

    validator = instance_of(MyClass)
    obj = SubClass(x=1)

    # Should pass without raising for a subclass instance
    validator(obj, obj.__attrs_attrs__[0], obj)

