import pytest
from marshmallow.schema import Schema
from marshmallow import fields
from marshmallow.exceptions import ValidationError

class TestSchemaMutation:
    def test_schema_load_unknown_fields(self):
        class UserSchema(Schema):
            name = fields.String()
            age = fields.Integer()

            class Meta:
                unknown = 'raise'

        schema = UserSchema()

        # Test with valid data
        valid_data = {"name": "Alice", "age": 30}
        result = schema.load(valid_data)
        assert result == {"name": "Alice", "age": 30}

        # Test with unknown field - this should raise if unknown='raise'
        invalid_data = {"name": "Bob", "age": 25, "email": "bob@example.com"}
        with pytest.raises(ValidationError):
            schema.load(invalid_data)

        # Test with missing field
        missing_data = {"name": "Charlie"}
        with pytest.raises(ValidationError):
            schema.load(missing_data)

        # Test with extra field but unknown='exclude'
        class ExcludeSchema(Schema):
            name = fields.String()

            class Meta:
                unknown = 'exclude'

        exclude_schema = ExcludeSchema()
        result = exclude_schema.load({"name": "Dave", "extra": 123})
        assert result == {"name": "Dave"}

        # Test with extra field but unknown='include'
        class IncludeSchema(Schema):
            name = fields.String()

            class Meta:
                unknown = 'include'

        include_schema = IncludeSchema()
        result = include_schema.load({"name": "Eve", "extra": 456})
        assert result == {"name": "Eve", "extra": 456}
